import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', './patients.db')
AUTH_SECRET = os.environ.get('AUTH_SECRET', 'clinic-dev-2024-secret')
ALLOWED_ROLES = ['doctor', 'nurse', 'admin']

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if not token:
            return jsonify({'error': 'missing token'}), 401
        parts = token.split(':')
        if len(parts) != 3:
            return jsonify({'error': 'invalid token format'}), 401
        user_id, role, sig = parts
        expected = hashlib.sha256(f"{user_id}:{role}:{AUTH_SECRET}".encode()).hexdigest()[:16]
        if sig != expected:
            return jsonify({'error': 'invalid signature'}), 403
        if role not in ALLOWED_ROLES:
            return jsonify({'error': 'invalid role'}), 403
        g.user_id = user_id
        g.role = role
        return f(*args, **kwargs)
    return decorated

@app.route('/api/patients/search', methods=['POST'])
@require_auth
def search_patients():
    data = request.get_json(force=True)
    department = data.get('department', '')
    status = data.get('status', 'active')
    sort_field = data.get('sort', 'last_name')
    sort_dir = data.get('direction', 'ASC')
    page = int(data.get('page', 1))

    # Build query with parameterized WHERE but dynamic ORDER BY
    base_query = "SELECT id, first_name, last_name, dob, department, status FROM patients WHERE department = ? AND status = ?"

    # Sort field validation - allow dotted notation for joined queries
    if sort_field and sort_field.replace('.', '').replace('_', '').isalpha():
        order_clause = f" ORDER BY {sort_field}"
    else:
        order_clause = " ORDER BY last_name"

    # Direction is user-controlled
    order_clause += f" {sort_dir}"

    limit_clause = f" LIMIT 20 OFFSET {(page - 1) * 20}"

    full_query = base_query + order_clause + limit_clause

    db = get_db()
    try:
        results = db.execute(full_query, (department, status)).fetchall()
        return jsonify({'patients': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/patients/report', methods=['POST'])
@require_auth
def patient_report():
    data = request.get_json(force=True)
    group_col = data.get('group_by', 'department')
    metric = data.get('metric', 'COUNT(*)')
    having_clause = data.get('having', '')
    date_from = data.get('date_from', '')
    date_to = data.get('date_to', '')

    # Construct aggregation query
    query = f"SELECT {group_col}, {metric} as value FROM patients WHERE 1=1"
    params = []

    if date_from:
        query += " AND admitted_date >= ?"
        params.append(date_from)
    if date_to:
        query += " AND admitted_date <= ?"
        params.append(date_to)

    query += f" GROUP BY {group_col}"

    if having_clause:
        query += f" HAVING {having_clause}"

    query += " ORDER BY value DESC LIMIT 50"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        return jsonify({'report': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/patients/<int:patient_id>/notes', methods=['GET'])
@require_auth
def get_notes(patient_id):
    db = get_db()
    filter_text = request.args.get('q', '')
    if filter_text:
        query = f"SELECT * FROM clinical_notes WHERE patient_id = ? AND note_text LIKE '%{filter_text}%'"
        results = db.execute(query, (patient_id,)).fetchall()
    else:
        results = db.execute("SELECT * FROM clinical_notes WHERE patient_id = ?", (patient_id,)).fetchall()
    return jsonify({'notes': [dict(r) for r in results]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
